PAGE_LENGTH = 500
MAX_PACK = 10

log("Data Cleanup File: start")
rules = frappe.get_doc("Data Cleanup Rules")
today = frappe.utils.getdate()
log("Data Cleanup File: today=%s" % (today,))
deleted_total = 0
for row in (rules.file_rules or []):
    if not row.get("enabled") or not row.get("days"):
        log("Data Cleanup File rule skipped (disabled or no days)")
        continue
    cutoff = frappe.utils.add_days(today, -int(row.days))
    log("Data Cleanup File rule days=%s attached_to_doctype=%s cutoff=%s" % (row.days, row.get("attached_to_doctype") or "all", cutoff))
    doctypes_to_consider = [row.attached_to_doctype] if row.get("attached_to_doctype") else frappe.get_all(
        "File", filters=[["attached_to_doctype", "!=", ""]], pluck="attached_to_doctype", distinct=1)
    count = 0
    for ref_dt in (doctypes_to_consider or []):
        if not ref_dt or not frappe.db.exists("DocType", ref_dt) or frappe.db.get_value("DocType", ref_dt, "issingle"):
            continue
        ref_start = 0
        while True:
            ref_names = frappe.get_all(ref_dt, filters=[["modified", "<", cutoff]], fields=["name"], order_by="name", limit_start=ref_start, limit_page_length=PAGE_LENGTH, pluck="name")
            if not ref_names:
                break
            file_filters = [["attached_to_doctype", "=", ref_dt], ["attached_to_name", "in", ref_names]]
            if row.get("file_type"):
                file_filters.append(["file_type", "=", row.file_type])
            if row.get("visibility") == "Private":
                file_filters.append(["is_private", "=", 1])
            elif row.get("visibility") == "Public":
                file_filters.append(["is_private", "=", 0])
            if row.get("folder"):
                file_filters.append(["folder", "=", row.folder])
            if row.get("file_size") is not None:
                file_filters.append(["file_size", ">=", int(row.file_size)])
            if row.get("attached_to_field"):
                file_filters.append(["attached_to_field", "=", row.attached_to_field])
            file_names = frappe.get_all("File", filters=file_filters, pluck="name")
            pack_count = 0
            for name in file_names:
                try:
                    frappe.delete_doc("File", name, force=1, ignore_permissions=True)
                    pack_count = pack_count + 1
                    count = count + 1
                    if pack_count >= MAX_PACK:
                        frappe.db.commit()
                        log("Data Cleanup File: committed batch of %s" % (MAX_PACK,))
                        pack_count = 0
                except Exception as e:
                    frappe.log_error("Data Cleanup File delete error for %s" % (name,), e)
                    log("Data Cleanup: error deleting File %s (see Error Log)" % (name,))
            if pack_count:
                frappe.db.commit()
            ref_start = ref_start + PAGE_LENGTH
    deleted_total = deleted_total + count
    log("Data Cleanup File rule days=%s attached_to_doctype=%s deleted=%s" % (row.days, row.get("attached_to_doctype") or "all", count))
    # Orphans: no link or broken link (use record modified date)
    log("Data Cleanup File: processing orphans (no link or broken link) cutoff=%s" % (cutoff,))
    count_no_link = 0
    orphan_start = 0
    while True:
        no_link_filters = [["modified", "<", cutoff]]
        no_link_or = [["attached_to_doctype", "=", ""], ["attached_to_name", "=", ""], ["is_folder","!=",1]]
        if row.get("file_type"):
            no_link_filters.append(["file_type", "=", row.file_type])
        if row.get("visibility") == "Private":
            no_link_filters.append(["is_private", "=", 1])
        elif row.get("visibility") == "Public":
            no_link_filters.append(["is_private", "=", 0])
        if row.get("folder"):
            no_link_filters.append(["folder", "=", row.folder])
        if row.get("file_size") is not None:
            no_link_filters.append(["file_size", ">=", int(row.file_size)])
        if row.get("attached_to_field"):
            no_link_filters.append(["attached_to_field", "=", row.attached_to_field])
        file_names = frappe.get_all("File", filters=no_link_filters, or_filters=no_link_or, fields=["name"], order_by="modified", limit_start=orphan_start, limit_page_length=PAGE_LENGTH, pluck="name")
        if not file_names:
            break
        pack_count = 0
        error_count = 0
        for name in file_names:
            try:
                frappe.delete_doc("File", name, force=1, ignore_permissions=True)
                pack_count = pack_count + 1
                count_no_link = count_no_link + 1
                if pack_count >= MAX_PACK:
                    frappe.db.commit()
                    log("Data Cleanup File: committed batch of %s" % (MAX_PACK,))
                    pack_count = 0
            except Exception as e:
                error_count = error_count + 1
                frappe.log_error("Data Cleanup File delete error (orphan no-link) %s" % (name,), e)
                log("Data Cleanup: error deleting File %s (see Error Log)" % (name,))
            if pack_count:
                frappe.db.commit()
                pack_count = 0
        orphan_start = orphan_start + PAGE_LENGTH - len ( file_names ) + error_count
    log("Data Cleanup File: orphan no-link deleted=%s" % (count_no_link,))
    deleted_total = deleted_total + count_no_link
    count_broken = 0
    orphan_start = 0
    while True:
        broken_filters = [["modified", "<", cutoff], ["attached_to_doctype", "!=", ""], ["attached_to_name", "!=", ""], ["is_folder","!=",1]]
        if row.get("file_type"):
            broken_filters.append(["file_type", "=", row.file_type])
        if row.get("visibility") == "Private":
            broken_filters.append(["is_private", "=", 1])
        elif row.get("visibility") == "Public":
            broken_filters.append(["is_private", "=", 0])
        if row.get("folder"):
            broken_filters.append(["folder", "=", row.folder])
        if row.get("file_size") is not None:
            broken_filters.append(["file_size", ">=", int(row.file_size)])
        if row.get("attached_to_field"):
            broken_filters.append(["attached_to_field", "=", row.attached_to_field])
        rows_page = frappe.get_all("File", filters=broken_filters, fields=["name", "attached_to_doctype", "attached_to_name"], order_by="modified", limit_start=orphan_start, limit_page_length=PAGE_LENGTH)
        if not rows_page:
            break
        to_delete = []
        for r in rows_page:
            if not frappe.db.exists(r.attached_to_doctype, r.attached_to_name):
                to_delete.append(r.name)
        pack_count = 0
        error_count = 0
        for name in to_delete:
            try:
                frappe.delete_doc("File", name, force=1, ignore_permissions=True)
                pack_count = pack_count + 1
                count_broken = count_broken + 1
                if pack_count >= MAX_PACK:
                    frappe.db.commit()
                    log("Data Cleanup File: committed batch of %s" % (MAX_PACK,))
                    pack_count = 0
            except Exception as e:
                error_count = error_count + 1
                frappe.log_error("Data Cleanup File delete error (orphan broken-link) %s" % (name,), e)
                log("Data Cleanup: error deleting File %s (see Error Log)" % (name,))
            if pack_count:
                frappe.db.commit()
                pack_count = 0
        orphan_start = orphan_start + PAGE_LENGTH - len( to_delete ) + error_count
    log("Data Cleanup File: orphan broken-link deleted=%s" % (count_broken,))
    deleted_total = deleted_total + count_broken
log("Data Cleanup File: finished total_deleted=%s" % (deleted_total,))
